@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Cormorant+Garamond:wght@400;500;600;700&display=swap');
.mfp.mfp-gsu.mfp-native-generated {--gsu-primary:#B8860B;--gsu-accent:#D4A520;--gsu-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--gsu-text:var(--mf-page-text,var(--mf-preset-text,#1A1A1A));--gsu-muted:var(--mf-page-muted,var(--mf-preset-muted,#8C7A5E));--gsu-border:var(--mf-page-border,var(--mf-preset-border,#E8D9B0));--gsu-on-primary:var(--mf-preset-on-primary,#FFFFFF);--gsu-deco:#F5E6B8;--gsu-page:#FFFBF2;--gsu-fill:#FFFBF2;--gsu-fill-strong:color-mix(in srgb, var(--gsu-text) 9%, var(--gsu-surface));--gsu-soft:color-mix(in srgb, var(--gsu-primary) 12%, var(--gsu-surface));--gsu-hairline:color-mix(in srgb, var(--gsu-text) 12%, var(--gsu-surface));}.mfp.mfp-gsu.mfp-native-generated {background:transparent!important;border:0!important;padding:0!important;font-family:'DM Sans',system-ui,-apple-system,'Segoe UI',sans-serif}.mfp.mfp-gsu.mfp-native-generated {--gsu-primary:var(--mf-page-primary,var(--mf-preset-primary,#B8860B));--gsu-accent:var(--mf-page-accent,var(--mf-preset-accent,#D4A520));--gsu-surface:var(--mf-page-surface,var(--mf-preset-surface,#FFFFFF));--gsu-text:var(--mf-page-text,var(--mf-preset-text,#1A1A1A));--gsu-border:var(--mf-page-border,var(--mf-preset-border,#E8D9B0));--gsu-on-primary:var(--mf-page-on-primary,var(--mf-preset-on-primary,#FFFFFF));--gsu-page:var(--mf-preset-bg,#FFFBF2);}@container (max-width:520px){.mfp.mfp-gsu.mfp-native-generated [class*="-grid"],.mfp.mfp-gsu.mfp-native-generated [class*="-meta"],.mfp.mfp-gsu.mfp-native-generated [class*="-scores"],.mfp.mfp-gsu.mfp-native-generated [class*="-charts"],.mfp.mfp-gsu.mfp-native-generated [class*="-cols"]{grid-template-columns:1fr!important}.mfp.mfp-gsu.mfp-native-generated [class*="-body"],.mfp.mfp-gsu.mfp-native-generated [class*="-split"],.mfp.mfp-gsu.mfp-native-generated [class*="-foot"],.mfp.mfp-gsu.mfp-native-generated [class*="-head"],.mfp.mfp-gsu.mfp-native-generated [class*="-row"]{flex-wrap:wrap!important}.mfp.mfp-gsu.mfp-native-generated [class*="-aside"],.mfp.mfp-gsu.mfp-native-generated [class*="-side"]{flex:1 1 100%!important;width:100%!important;max-width:none!important}}.mfp.mfp-gsu.mfp-native-generated  img{max-width:100%!important;height:auto}.mfp.mfp-gsu.mfp-native-generated {overflow-wrap:break-word}

/* The wrapper itself: strip the host's card, but NOT its width. Layout > Max width in the module
   settings (480/640/768/960/Full) is a max-width on THIS element, and the previous version of this
   rule overrode it with max-width:none!important - so picking 960 did nothing at all. */
.mf-form-wrapper:has(.mfp-gsu){background:transparent!important;border:0!important;
  border-radius:0!important;box-shadow:none!important;padding:0!important}
/* The boxes INSIDE it have their own measures, and those are what squeezed the design. */
.mf-form-wrapper:has(.mfp-gsu) > .mf-form-inner,
.mf-form-wrapper:has(.mfp-gsu) .mf-form,
.mf-form-wrapper:has(.mfp-gsu) .mf-fields-container{background:transparent!important;
  border:0!important;border-radius:0!important;box-shadow:none!important;padding:0!important;
  margin:0!important;max-width:none!important;width:100%!important}

.mfp.mfp-gsu.mfp-native-generated {container-type:inline-size;font-family:'DM Sans',system-ui,-apple-system,'Segoe UI',sans-serif!important;color:var(--gsu-text)}
.mfp.mfp-gsu.mfp-native-generated .gsu-page{background:var(--gsu-page)}

/* full-bleed hero -------------------------------------------------------- */
.mfp.mfp-gsu.mfp-native-generated .gsu-hero{position:relative;overflow:hidden;height:320px;
  background-image:url('/DesktopModules/MegaForm/Assets/img/gold-suite-membership-application/hotel-suite-hero.png'),url('/Modules/MegaForm/img/gold-suite-membership-application/hotel-suite-hero.png');
  background-size:cover;background-position:50% 50%}
.mfp.mfp-gsu.mfp-native-generated img.gsu-content-image{position:absolute!important;inset:0!important;display:block!important;
  width:100%!important;height:100%!important;object-fit:cover!important;object-position:50% 50%!important;
  border:0!important;border-radius:0!important;pointer-events:none!important}
.mfp.mfp-gsu.mfp-native-generated .gsu-hero-scrim{position:absolute;inset:0;
  background:linear-gradient(to right,rgba(26,26,26,.7) 0%,rgba(26,26,26,.1) 60%)}
.mfp.mfp-gsu.mfp-native-generated .gsu-hero-copy{position:absolute;inset:0;display:flex;flex-direction:column;
  justify-content:center;padding:0 32px}
@container (min-width:640px){.mfp.mfp-gsu.mfp-native-generated .gsu-hero-copy{padding:0 64px}}
.mfp.mfp-gsu.mfp-native-generated p.gsu-hero-eyebrow{margin:0 0 8px!important;font-size:12px!important;line-height:16px!important;
  font-weight:700!important;letter-spacing:.25em!important;text-transform:uppercase!important;
  color:var(--gsu-accent)!important}
.mfp.mfp-gsu.mfp-native-generated h1.gsu-hero-h{margin:0!important;font-family:'Cormorant Garamond',Georgia,'Times New Roman',serif!important;font-size:60px!important;
  line-height:1!important;font-weight:700!important;color:#fff!important}
.mfp.mfp-gsu.mfp-native-generated h1.gsu-hero-h em{font-style:normal;color:var(--gsu-accent)}
.mfp.mfp-gsu.mfp-native-generated p.gsu-hero-lede{margin:12px 0 0!important;max-width:384px;font-size:14px!important;
  line-height:20px!important;font-weight:400!important;color:rgba(255,255,255,.75)!important}
.mfp.mfp-gsu.mfp-native-generated .gsu-pills{position:absolute;right:20px;bottom:20px;display:flex;gap:12px}
.mfp.mfp-gsu.mfp-native-generated .gsu-pill{border-radius:16px;padding:10px 16px;text-align:center;
  background:rgba(253,240,204,.92)}
@container (max-width:520px){
  .mfp.mfp-gsu.mfp-native-generated .gsu-pills{left:12px;right:12px;gap:6px}
  .mfp.mfp-gsu.mfp-native-generated .gsu-pill{flex:1 1 0;min-width:0;padding:8px 6px}
}
.mfp.mfp-gsu.mfp-native-generated .gsu-pill-top{display:flex;align-items:center;justify-content:center;gap:6px}
.mfp.mfp-gsu.mfp-native-generated .gsu-pill-top i{font-size:14px;line-height:14px;color:var(--gsu-primary)}
.mfp.mfp-gsu.mfp-native-generated .gsu-pill-v{font-size:16px;line-height:24px;font-weight:700;color:var(--gsu-text)}
.mfp.mfp-gsu.mfp-native-generated .gsu-pill-s{font-size:10px;line-height:15px;font-weight:500;color:#8C7A5E}

/* content column --------------------------------------------------------- */
.mfp.mfp-gsu.mfp-native-generated .gsu-main{max-width:896px;margin:0 auto;padding:40px 32px}
.mfp.mfp-gsu.mfp-native-generated .gsu-block{margin-top:40px}
.mfp.mfp-gsu.mfp-native-generated .gsu-sec{display:flex;align-items:center;gap:12px;padding-bottom:12px;
  border-bottom:1px solid var(--gsu-border)}
.mfp.mfp-gsu.mfp-native-generated .gsu-sec-pill{width:6px;height:20px;border-radius:999px;background:var(--gsu-accent);flex:0 0 auto}
.mfp.mfp-gsu.mfp-native-generated h2.gsu-sec-h{margin:0!important;font-family:'Cormorant Garamond',Georgia,'Times New Roman',serif!important;font-size:20px!important;
  line-height:28px!important;font-weight:600!important;color:var(--gsu-text)!important}
.mfp.mfp-gsu.mfp-native-generated .gsu-tiers{margin-top:16px}
.mfp.mfp-gsu.mfp-native-generated .gsu-grid2{display:grid;grid-template-columns:1fr 1fr;column-gap:24px;row-gap:20px;
  margin-top:20px}
.mfp.mfp-gsu.mfp-native-generated .gsu-span2{grid-column:1/-1}
.mfp.mfp-gsu.mfp-native-generated .gsu-field{display:block;margin:0}
.mfp.mfp-gsu.mfp-native-generated .gsu-label{display:block;margin:0 0 6px;font-size:10px;line-height:15px;font-weight:600;
  letter-spacing:.1em;text-transform:uppercase;color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-chips{margin-top:16px}
.mfp.mfp-gsu.mfp-native-generated .gsu-mot{display:block;margin-top:32px}
.mfp.mfp-gsu.mfp-native-generated .gsu-mot .mf-textarea[class]{margin-top:6px!important}

/* megaform sets font-family on label/input/select/textarea with !important, so an authored
   <span> inside a <label> inherits the HOST typeface no matter what the shell root declares.
   Element selectors are (0,3,1) here - above megaform, below every authored class rule - and
   <i> is left alone so Font Awesome keeps its own family. */
.mfp.mfp-gsu.mfp-native-generated label,.mfp.mfp-gsu.mfp-native-generated span,.mfp.mfp-gsu.mfp-native-generated p,.mfp.mfp-gsu.mfp-native-generated div,.mfp.mfp-gsu.mfp-native-generated ul,.mfp.mfp-gsu.mfp-native-generated li,.mfp.mfp-gsu.mfp-native-generated h1,.mfp.mfp-gsu.mfp-native-generated h2,.mfp.mfp-gsu.mfp-native-generated h3,.mfp.mfp-gsu.mfp-native-generated button{font-family:inherit!important}
.mfp.mfp-gsu.mfp-native-generated .mf-field-label{display:none!important}
/* A wizard's page-break Section renders a visible heading the mock has no room for - it exists to
   split the pages, not to be seen. */
.mfp.mfp-gsu.mfp-native-generated .mf-section-break,.mfp.mfp-gsu.mfp-native-generated .mf-section-title{display:none!important}
.mfp.mfp-gsu.mfp-native-generated .mf-field-group{margin:0!important;width:100%}
.mfp.mfp-gsu.mfp-native-generated .mf-form-title,.mfp.mfp-gsu.mfp-native-generated .mf-form-description,.mfp.mfp-gsu.mfp-native-generated .mf-form-actions{display:none!important}
.mfp.mfp-gsu.mfp-native-generated .mf-option-item{margin:0!important}
/* megaform gives every option chip a 36px floor and paints .mf-option-icon as a rounded tile. */
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips .mf-option-check,
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-check{display:none!important}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips .mf-option-ui{min-height:0!important;height:auto!important}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-copy{display:block;width:100%}


.mfp.mfp-gsu.mfp-native-generated .mf-input[class],.mfp.mfp-gsu.mfp-native-generated .mf-select[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--gsu-border)!important;border-radius:12px!important;background:var(--gsu-surface)!important;
  padding:12px 16px!important;min-height:0!important;height:auto!important;
  color:var(--gsu-text)!important;font-family:inherit!important;font-size:14px!important;
  line-height:20px!important;font-weight:400!important;box-shadow:none!important}
.mfp.mfp-gsu.mfp-native-generated .mf-input[class]:focus,.mfp.mfp-gsu.mfp-native-generated .mf-select[class]:focus{border-color:var(--gsu-accent)!important;
  box-shadow:none!important;outline:none!important}
.mfp.mfp-gsu.mfp-native-generated .mf-input[class]::placeholder,.mfp.mfp-gsu.mfp-native-generated .mf-textarea[class]::placeholder{color:#8C7A5E!important;opacity:1}


.mfp.mfp-gsu.mfp-native-generated .mf-textarea[class]{width:100%!important;box-sizing:border-box!important;
  border:1px solid var(--gsu-border)!important;border-radius:12px!important;background:#fff!important;
  padding:12px 16px!important;min-height:106px!important;height:106px!important;
  resize:none!important;color:var(--gsu-text)!important;font-family:inherit!important;
  font-size:14px!important;line-height:20px!important;box-shadow:none!important}

/* tier cards ------------------------------------------------------------- */
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards{display:grid!important;grid-template-columns:1fr 1fr 1fr!important;
  gap:16px!important}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-ui{display:flex;flex-direction:column;align-items:stretch;
  gap:0;width:100%;box-sizing:border-box;padding:20px;border:2px solid var(--gsu-border);
  border-radius:16px;background:#fff;cursor:pointer;transition:all .15s ease}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-icon{display:flex!important;align-items:center!important;
  justify-content:center!important;width:40px!important;height:40px!important;flex:0 0 40px!important;
  margin:0 0 12px!important;padding:0!important;border:0!important;border-radius:12px!important;
  background:#F5E6B8!important;color:var(--gsu-primary)!important;font-size:20px!important;
  line-height:20px!important}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-label{font-size:14px;line-height:20px;font-weight:700;
  color:var(--gsu-text)}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-desc{display:block;width:100%;margin:0;font-size:12px;
