.mfp.mfp-gsu.mfp-native-generated .gsu-price{display:block;margin-top:2px;font-size:20px;line-height:28px;font-weight:700;
  color:var(--gsu-primary)}
.mfp.mfp-gsu.mfp-native-generated .gsu-period{display:block;margin-top:2px;margin-bottom:12px;font-size:12px;line-height:16px;
  color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-pop{display:block;margin-bottom:12px}
.mfp.mfp-gsu.mfp-native-generated .gsu-pop-row{display:flex;justify-content:space-between;margin-bottom:4px;font-size:10px;
  line-height:15px}
.mfp.mfp-gsu.mfp-native-generated .gsu-pop-l{color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-pop-r{font-weight:700;color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-pop-d{font-weight:400}
.mfp.mfp-gsu.mfp-native-generated .gsu-bar{display:block;height:6px;border-radius:999px;overflow:hidden;background:var(--gsu-border)}
.mfp.mfp-gsu.mfp-native-generated .gsu-bar-f{display:block;height:100%;border-radius:999px;background:#F5E6B8}
.mfp.mfp-gsu.mfp-native-generated .gsu-bar-82{width:82%}
.mfp.mfp-gsu.mfp-native-generated .gsu-bar-75{width:75%}
.mfp.mfp-gsu.mfp-native-generated .gsu-bar-68{width:68%}
.mfp.mfp-gsu.mfp-native-generated .gsu-perks{display:block}
.mfp.mfp-gsu.mfp-native-generated .gsu-perk{display:flex;align-items:center;gap:6px;margin-bottom:4px;font-size:12px;
  line-height:16px;color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-perk:last-child{margin-bottom:0}
.mfp.mfp-gsu.mfp-native-generated .gsu-perk::before{content:'\2713';flex:0 0 auto;font-size:12px;line-height:16px;
  font-weight:700;color:var(--gsu-primary)}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards input:checked+.mf-option-ui{border-color:var(--gsu-accent);background:#FEF6E0}
@container (max-width:520px){
  .mfp.mfp-gsu.mfp-native-generated .mf-option-group--cards{grid-template-columns:1fr!important}
}

/* experience pills ------------------------------------------------------- */
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips{display:flex;flex-wrap:wrap;gap:8px}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips .mf-option-ui{display:block;gap:0;padding:6px 16px;
  border:1px solid var(--gsu-border);border-radius:9999px;background:#fff;color:#8C7A5E;font-size:14px;
  line-height:20px;font-weight:500;text-align:center;cursor:pointer;transition:all .15s ease}
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips .mf-option-label{font-size:14px;line-height:20px;font-weight:500;
