.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips .mf-option-item.is-selected .mf-option-ui,
.mfp.mfp-gsu.mfp-native-generated .mf-option-group--chips input:checked+.mf-option-ui{background:var(--gsu-accent);border-color:var(--gsu-accent);
  color:var(--gsu-text)}

