.mfp.mfp-gsu.mfp-native-generated .gsu-terms .mf-option-ui{display:flex;align-items:flex-start;gap:12px;padding:0;border:0;
  background:transparent}
.mfp.mfp-gsu.mfp-native-generated .gsu-terms .mf-option-label{font-size:14px;line-height:20px;font-weight:400;color:#8C7A5E}
.mfp.mfp-gsu.mfp-native-generated .gsu-link{text-decoration:underline;font-weight:600;color:var(--gsu-primary)}
.mfp.mfp-gsu.mfp-native-generated button.gsu-submit[type="submit"]{display:block;width:100%!important;margin-top:24px!important;
  padding:16px 0!important;border:0!important;border-radius:16px!important;
  background:linear-gradient(135deg,#8B5E0A 0%,var(--gsu-accent) 100%)!important;color:#fff!important;
  font-family:inherit!important;font-size:14px!important;line-height:20px!important;
  font-weight:700!important;letter-spacing:.1em!important;text-transform:uppercase!important;
  cursor:pointer!important;box-shadow:none!important}
.mfp.mfp-gsu.mfp-native-generated button.gsu-submit.mf-nav-blocked,.mfp.mfp-gsu.mfp-native-generated button.gsu-submit[disabled]{opacity:1;
  background:linear-gradient(135deg,#8B5E0A 0%,var(--gsu-accent) 100%)!important;
  cursor:not-allowed!important;filter:none!important}
.mfp.mfp-gsu.mfp-native-generated p.gsu-foot{margin:16px 0 0!important;text-align:center!important;font-size:12px!important;
  line-height:16px!important;font-weight:400!important;color:#8C7A5E!important}
.mfp.mfp-gsu.mfp-native-generated .gsu-page{padding:0!important;background:transparent!important;min-height:0!important}.mfp.mfp-gsu.mfp-native-generated .gsu-shell,.mfp.mfp-gsu.mfp-native-generated .gsu-wrap{max-width:none!important;margin:0!important}.mfp.mfp-gsu.mfp-native-generated .gsu-grid,.mfp.mfp-gsu.mfp-native-generated .gsu-main,.mfp.mfp-gsu.mfp-native-generated .gsu-hero-in,.mfp.mfp-gsu.mfp-native-generated .gsu-card{max-width:none!important;margin-left:0!important;margin-right:0!important}.mfp.mfp-gsu.mfp-native-generated .gsu-page{border:1px solid var(--gsu-border)!important;border-radius:12px!important;overflow:hidden;background:var(--gsu-page)!important}.mf-form-wrapper.mf-has-date-popover .mfp.mfp-gsu.mfp-native-generated .gsu-page{overflow:visible!important}
